    best = None
    max_h, max_w = min(h, 18), min(w, 18)
    for sh in range(2, max_h + 1):
        for sw in range(2, max_w + 1):
            windows = []
            for r in range(h - sh + 1):
                for c in range(w - sw + 1):
                    patch = [row[c:c + sw] for row in grid[r:r + sh]]
                    mass = sum(v != 0 for row in patch for v in row)
                    if mass >= 12:
                        windows.append((r, c, patch, mass))
            for i, a in enumerate(windows):
                ar, ac, ap, am = a
                for br, bc, bp, bm in windows[i + 1:]:
                    # Copies must be spatially separate, not overlapping windows.
                    if not (ar + sh <= br or br + sh <= ar or
